func TestNewEnvelopeTomaActorYCorrelationDelContexto(t *testing.T) {
	ctx := WithActor(WithCorrelationID(context.Background(), "corr-1"), "user-9")
	env, err := New(ctx, ProducerEducacion, InscripcionCreada, InscripcionCreadaPayload{InscripcionID: "i1", CursoID: "c1", ParticipanteID: "p1"})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	if !IsUUID(env.EventID) {
		t.Errorf("event_id no es uuid: %q", env.EventID)
	}
	if env.CorrelationID != "corr-1" || env.ActorID != "user-9" {
		t.Errorf("contexto no propagado: %+v", env)
	}
	if env.Version != 1 || env.Producer != ProducerEducacion || env.EventType != InscripcionCreada {
		t.Errorf("campos fijos incorrectos: %+v", env)
	}
	if env.OccurredAt.Location() != time.UTC {
		t.Errorf("occurred_at debe estar en UTC")
	}
}

