func TestEnvelopeSerializacionIdaYVuelta(t *testing.T) {
	env, err := NewWithID(context.Background(), NameUUID("x"), ProducerContentful, ContenidoPublicado, ContenidoPayload{EntryID: "e1", Accion: "publish", Revision: 3})
	if err != nil {
		t.Fatal(err)
	}
	data, err := env.Marshal()
	if err != nil {
		t.Fatal(err)
	}

	// Los nombres de los campos son el contrato con otros servicios.
	var raw map[string]any
	if err := json.Unmarshal(data, &raw); err != nil {
		t.Fatal(err)
	}
	for _, k := range []string{"event_id", "event_type", "version", "occurred_at", "producer", "correlation_id", "actor_id", "payload"} {
		if _, ok := raw[k]; !ok {
			t.Errorf("falta el campo %q en el JSON", k)
		}
	}
	if _, err := time.Parse(time.RFC3339, raw["occurred_at"].(string)); err != nil {
		t.Errorf("occurred_at no es RFC3339: %v", err)
	}

	back, err := Decode(data)
	if err != nil {
		t.Fatal(err)
	}
	if back.EventID != env.EventID || !back.OccurredAt.Equal(env.OccurredAt) || string(back.Payload) != string(env.Payload) {
		t.Errorf("ida y vuelta distinta: %+v vs %+v", back, env)
	}
	p, err := DecodePayload[ContenidoPayload](back)
	if err != nil || p.EntryID != "e1" || p.Revision != 3 {
		t.Errorf("payload: %+v, %v", p, err)
	}
}

