func TestDecodeRechazaInvalidos(t *testing.T) {
	cases := map[string]string{
		"no es json":   `{`,
		"sin campos":   `{}`,
		"id no uuid":   `{"event_id":"1","event_type":"a","version":1,"occurred_at":"2026-01-01T00:00:00Z","producer":"p","correlation_id":"c","payload":{}}`,
		"version cero": `{"event_id":"` + NewUUID() + `","event_type":"a","version":0,"occurred_at":"2026-01-01T00:00:00Z","producer":"p","correlation_id":"c","payload":{}}`,
		"payload null": `{"event_id":"` + NewUUID() + `","event_type":"a","version":1,"occurred_at":"2026-01-01T00:00:00Z","producer":"p","correlation_id":"c","payload":null}`,
	}
	for name, data := range cases {
		if _, err := Decode([]byte(data)); !errors.Is(err, ErrInvalidEnvelope) {
			t.Errorf("%s: se esperaba ErrInvalidEnvelope, llegó %v", name, err)
		}
	}
}

