func TestMemoryStoreAcotado(t *testing.T) {
	ctx := context.Background()
	s := NewMemoryStore(2)
	_ = s.MarkProcessed(ctx, "c", "1", "t")
	_ = s.MarkProcessed(ctx, "c", "1", "t")
	_ = s.MarkProcessed(ctx, "c", "2", "t")
	_ = s.MarkProcessed(ctx, "c", "3", "t")
	if ok, _ := s.IsProcessed(ctx, "c", "1"); ok {
		t.Error("el más viejo debió descartarse")
	}
	if ok, _ := s.IsProcessed(ctx, "c", "3"); !ok {
		t.Error("el último debe estar")
	}
	if ok, _ := s.IsProcessed(ctx, "otro", "3"); ok {
		t.Error("cada consumidor lleva su propia cuenta")
	}
	if NewMemoryStore(0).capacity != 1000 {
		t.Error("capacidad por defecto")
	}
}
